# Fix the algorithm - need to unpack tuples properly

def transform_grid_v2(grid):
    result = [row[:] for row in grid]
    bar_cols = [c for c in range(17) if grid[16][c] != 0]

    for col in bar_cols:
        non_zero = [(r, grid[r][col]) for r in range(16) if grid[r][col] != 0]
        non_zero.sort()
        bar_val = grid[16][col]

        if not non_zero:
            for r in range(16):
                result[r][col] = bar_val
            continue

        # Fill from row 0 to first non-zero with first non-zero's value
        first_row = non_zero[0]
        first_cell_val = first_row[1]
        for r in range(first_row[0]):
            if result[r][col] == 0:
                result[r][col] = first_cell_val

        # Fill between cells with next cell's value
        for k in range(len(non_zero) - 1):
            curr_row = non_zero[k]  # (row, val) tuple
            next_row = non_zero[k + 1]  # (row, val) tuple
            fill_with = next_row[1]
            for i in range(curr_row[0] + 1, next_row[0]):
                if result[i][col] == 0:
                    result[i][col] = fill_with

        # Fill from last cell to bar with bar's value
        last_row = non_zero[-1]
        for i in range(last_row[0] + 1, 16):
            if result[i][col] == 0:
                result[i][col] = bar_val

    return result

